        content:
          'Ein naturnaher Gartenteich (ab ca. 4–8 m²) bringt Libellen, Molche, Frösche und nützliche Insekten in den Garten:\n• Richtiger Standort: Halbsonnig (ca. 4–6 Std. Sonne/Tag — bei praller Dauersonne drohen Algenblüten!). NICHT direkt unter Laubbäumen oder Walnuss anlegen (fallendes Laub fault im Wasser und überdüngt den Teich).\n• Die 3 Zonen (entscheidend für Biologie & Frost!): 1. Sumpfrand (0–20 cm) für Sumpfdotterblume, Blutweiderich, Bachbunge; 2. Flachwasser (20–50 cm) für Froschlöffel, Fieberklee, Igelkolben; 3. Tiefwasserzone (mind. 80–100 cm tief — im Schwarzatal wichtig als frostfreie Überwinterungszone!).\n• Abdichtung & Kapillarsperre: Unter Teichfolie (EPDM-Kautschuk ~1,0–1,2 mm hält 30+ Jahre und bleibt weich) immer 300–500 g/m² Schutzvlies auf steinfreies Sandbett legen. Wichtigste Regel am Rand: Eine saubere Kapillarsperre bauen (Folie rundum ca. 5–10 cm über Bodenniveau auf einen kleinen Wall ziehen), damit kein nährstoffreicher Gartenboden/Dünger durch Regen in den Teich geschwemmt wird!\n• Füllung & Fische: Ideal ist kalkarmes Regenwasser oder weiches Leitungswasser (euer Rennsteigwasser < 8,4 °dH ist super geeignet!). Für Amphibien, Libellenlarven & biologisches Gleichgewicht KEINE Fische (Goldfische/Kois) einsetzen — Fische fressen Laich und trüben/überdüngen kleine Teiche.',
