        content:
          'Je weniger man in einem gut bepflanzten Naturteich „herumputzt“, desto klarer bleibt das Wasser:\n• Frühjahr (März–April): Abgestorbene Ufer- & Schilfhalme (waren im Winter wichtige Atemröhrchen!) knapp über der Wasseroberfläche abschneiden. Verfaultes Laub & Fadenalgen behutsam mit Kescher/Holzstock herausfischen. Unterwasserpflanzen (Hornblatt, Tausendblatt, Wasserpest — Sauerstoffproduzenten & Algen-Konkurrenten!) nachsetzen, falls < 1/3 der Fläche bedeckt ist.\n• Sommer (Algen-Schutz): Grüne Schwebealgen / Fadenalgen sind immer ein Zeichen für zu viele Nährstoffe + viel Sonne. Keine Chemie/Algizide (tötet Insektenlarven!). Stattdessen: Fadenalgen auf einen Stock aufwickeln, Schwimmpflanzen (Froschbiss, Seerose für ca. 30–40 % Beschattung) nutzen und nicht mit Teichschlamm-Dünger arbeiten. Verdunstetes Wasser mit Regenwasser nachfüllen.\n• Herbst (Oktober–November): Laubschutznetz locker über den Teich spannen, bevor das große Herbstlaub fällt — das verhindert 80 % der Faulgase im Winter.\n• Winter: Nie gewaltsam ins Eis schlagen (Druckwellen verletzen überwinternde Frösche tödlich!). Stehende Schilf-/Rohrkolbenhalme oder ein schwimmender Eisfreihalter aus Styropor/Holz sorgen für Gasaustausch.',
