        content:
          'Gezielte, giftfreie Praxis-Strategien für die häufigsten Gartenplagen (schonen Igel, Vögel, Bienen & Glühwürmchen!):\n• Nacktschnecken: Abends oder frühmorgens nach Regen absammeln; rund um empfindliche Jungpflanzen Schneckenkragen oder grobes Schafwoll-/Sägemehlband legen. Hochbeete mit überhängendem Kupfer-/Blechrand sichern. KEIN Schneckenkorn mit Metaldehyd (vergiftet Igel!) und auch bei Eisen-III-Phosphat sparsam sein, da es auch nützliche Gehäuseschnecken trifft. Gießen immer morgens statt abends (trockene Beete über Nacht bremsen Schnecken massiv!).\n• Blattläuse: Oft hilft schon ein kräftiger Wasserstrahl oder Abstreifen. Brennnessel-Kaltauszug (1 kg frische Brennnesseln 12–24 Std. in 10 L Wasser ziehen, unverdünnt sprühen) oder Schmierseifen-Lösung (1–2 % reine Kaliseife ohne Zusätze). Dauerlösung: Dill, Ringelblume, Schafgarbe & Tagetes für Marienkäfer, Flor- und Schwebfliegenlarven säen.\n• Kohlweißling, Kohlfliege & Möhrenfliege: Feinmaschiges Kulturschutznetz (Maschenweite ≤ 0,8–1,3 mm) direkt nach Saat/Pflanzung locker über das Beet spannen — schützt zu 100 % ohne jedes Mittel!\n• Wühlmäuse: Hochbeete unten mit engmaschigem verzinktem Drahtgitter (12–16 mm) auskleiden. Im Obstgarten frische Obstbaumwurzeln mit Drahtkorb schützen. Vergrämung durch tief gesteckte Holunderzweige, Knoblauchzehen oder Buttermilch-Molke-Gemisch in den Gängen sowie Sitzstangen („Julen“) für Turmfalke & Mäusebussard.',
        source: 'LWG Bayern / NABU / BUND – Ökologischer Pflanzenschutz',
        isVerifiedSource: true,
        safetyWarning:
          'Auch selbstgemachte Pflanzenbrühen (wie Rainfarn oder Rhabarberblatt) können Nützlinge oder Fische schädigen — niemals in Teichnähe spritzen und nur gezielt bei starkem Befall anwenden.',
        date: today,
        tags: ['Schädlinge', 'Schnecken', 'Blattläuse', 'Wühlmaus', 'Kulturschutznetz', 'Biologisch'],
