        content:
          'Ob Teichbau, Terrassenstufe, Fundament oder Wegebau — wer Aushub klug trennt, spart viel Geld und schützt wertvollen Gartenboden:\n• GOLDENE TRENN-REGEL: Immer zwei getrennte Planen/Lagerplätze anlegen!\n  1. Mutterboden / Oberboden (oberste 15–30 cm, dunkel, humos, voller Bodenleben & Regenwürmer): Separat abtragen und als wertvollste Schicht für Beete, Rasen und oberste Deckschicht aufbewahren.\n  2. Unterboden / Rohboden (darunter liegend, heller, steinig/lehmig, im Schwarzatal meist Schieferverwitterung): Niemals mit Mutterboden vermischen! Eignet sich ideal zum Unterfüttern von Terrassenstufen, Modellieren von Wällen, Hinterfüllen tiefer Geländesenken oder als unterster Kern im Hügelbeet.\n• Volumen-Überraschung (Auflockerungsfaktor!): Fest gewachsener Boden dehnt sich beim Ausheben durch Luft um ca. 20–30 % aus! Aus einem 4 m³ Teichloch entstehen also schnell 5–5,2 m³ lockerer Aushub (= ~7–8 Tonnen). Vor dem ersten Spatenstich festlegen, wohin das Material kommt.\n• Mutterboden richtig zwischenlagern: Haufen nicht höher als ~1,2–1,5 m locker schütten (niemals mit Bagger/Schubkarre verdichten!). Wenn der Haufen länger als 4–6 Wochen liegt, kurz mit Phacelia, Senf oder Weißklee begrünen — verhindert Verschlämmung und hält Bodenorganismen aktiv.',
