        content:
          'Saubere Wege und Einfassungen sparen im Alltag enorm viel Jätarbeit und halten neue Erde genau da, wo sie hingehört:\n• Trittplatten & Kies-/Splitwege richtig bauen: Ca. 15–20 cm tief auskoffern, seitlich Rasenkanten/Einfassung setzen, 10–12 cm Schotter 0/32 als Frostschutz-/Tragschicht lagenweise abrütteln oder stampfen, darauf ein Geotextil-Vlies (trennt Schotter von Splitt) und 3–5 cm Edelsplitt 2/5 mm abziehen. Trittplatten (z.B. Schiefer, Granit) mit Gummihammer satt einklopfen. Immer ca. 1,5–2 % leichtes Quergefälle vom Haus weg!\n• Einfache Natur-Gartenwege (ohne schweres Bauen): 10 cm ausheben, Unkrautvlies (wasserdurchlässig, kein Folienplastik!) auslegen und mit 8–10 cm grobem Holzhäcksel oder Rindenmulch füllen — weich zu laufen, versickert Starkregen sofort und wird alle 2–3 Jahre zu tollem Mulch.\n• Beeteinfassungen gegen Quecke & Rasen: Mind. 12–15 cm tief in die Erde setzen (Cortenstahlband, dicke Lärchenbohlen, hochkant gestellte Schiefer-/Granitsteine). Verhindert, dass Wiesengräser ins frische Gemüsebeet wandern.\n• Hangwasser bändigen: Bei den ~900 mm Jahresniederschlag im Schwarzatal läuft Regenwasser auf Hängen oberflächlich ab. Oberhalb großer Beete/Terrassen eine flache begrünte Wasserfangmulde (Swale) oder Kiesrinne mit leichtem Gefälle seitlich in eine Sickermulde führen.',
