        content:
          'Wer seine Hühner lesen kann, erkennt Wohlbefinden und Probleme Tage bevor es ernst wird:\n• FASZINIERENDE HÜHNER-FAKTEN:\n  – Hühner erkennen über 100 verschiedene Gesichter (Herdenmitglieder UND vertraute Menschen!) und träumen wie wir im REM-Schlaf.\n  – Ein Huhn im „Sonnenbad“ (liegt seitlich im Staub, ein Flügel abgespreizt, Augen halb zu) ist NICHT krank oder tot, sondern genießt pure UV-Entspannung zur Vitamin-D-Bildung!\n  – Hennen „singen“ oft stolz ihr „Ei-Lied“ (Gackern) nach dem Legen — ursprünglich, um nach der Ablage im Versteck wieder Anschluss an die Gruppe zu finden.\n• HACKORDNUNG & NEUE HÜHNER INTEGRIEREN (Pro-Tipp!):\n  – Niemals ein einzelnes neues Huhn allein tagsüber zur Gruppe setzen (wird gemobbt!) — immer mind. 2 neue Tiere zusammen einführen.\n  – Bester Trick: Abends im Dunkeln ruhig zu den anderen auf die Schlafstange setzen! Morgens wachen alle mit gemeinsamem Stallgeruch auf und es gibt viel weniger Streit; zusätzlich 2–3 Tage eine zweite Futter-/Tränkestelle aufstellen.\n• MAUSER (Herbst-Legepause):\n  – Im Herbst wechseln Hühner ihr gesamtes Federkleid (~6–10 Wochen) und legen in dieser Zeit kaum oder keine Eier. Keine Krankheit! Jetzt eiweißreiches Futter (etwas Bierhefe, geschälte Sonnenblumenkerne, Rührei/Quark in Maßen) für den Federaufbau geben.\n• NOTFALL LEGENOT ERKENNEN: Steht eine Henne wie ein „Pinguin“ aufrecht, presst rhythmisch, wirkt apathisch mit eingezogenem Kopf oder bläulichem Kamm, steckt ein Ei fest -> warmes feuchtes Tuch / handwarmes Sitzbad zur Muskelentspannung, 1–2 Tropfen warmes Speiseöl vorsichtig an die Kloake und bei Ausbleiben des Eis rasch zum geflügelkundigen Tierarzt!',
