        content:
          'Bewährte Praxis-Hacks aus jahrelanger Hobbyhaltung, die Zeit sparen und Verluste im Mittelgebirge verhindern:\n• RAUBTIERSCHUTZ (Im Schwarzatal rund um den Wald unverzichtbar!):\n  – Steinmarder passen durch jede Lücke ab ca. 3 cm! Lüftungsschlitze im Stall zwingend mit punktgeschweißtem Volierendraht (Masche ≤ 12–19 mm, Drahtstärke ≥ 1,0–1,4 mm — KEIN dünner Sechseck-Kaninchendraht, den beißt der Fuchs durch!) sichern.\n  – Fuchs-Grabschutz: Zaun 40–50 cm tief eingraben ODER noch einfacher als „Schürze“ (Apron) 50 cm breit außen flach auf dem Boden auslegen und mit Gras einwachsen lassen — der Fuchs gräbt direkt am Zaun und stößt sofort auf Draht!\n  – Automatische Hühnerklappe (Dämmerungssensor + Zeitfenster): Schließt zuverlässig vor Einbruch der Dämmerung, auch wenn ihr mal spät heimkommt.\n  – Habichtschutz: Sträucher/Obstbäume/Unterstände im Auslauf als Deckung (oder Überspannnetz) mindern Greifvogel-Risiko massiv.\n• KOTBRETT-HACK (Spart 80 % Mistarbeit!): Direkt ~15–20 cm unter den Schlafstangen ein abwischbares Brett (Siebdruckplatte oder Blech) mit etwas Hanfstreu/Zeitung anbringen. Da Hühner ~60 % ihres Kots nachts absetzen, ist der Stall mit 1 Min. täglich Abkratzen blitzsauber!\n• WELLNESS-STAUBBAD: Alte Mörtelwanne oder trockene Ecke unter Vordach mit 50 % trockenem Spielsand/trockener Gartenerde + 40 % gesiebter unbehandelter Holzasche + 10 % Kieselgur füllen — beste natürliche Vorbeugung gegen Federlinge & Milben!\n• WINTER-PROTIP: Bei Frost unter -10 °C Kämme/Kehllappen von großkämmigen Rassen dünn mit Vaseline oder Melkfett einreiben (schützt vor Erfrierungen!) und Tränkenwärmer nutzen; abends eine kleine Handvoll ganze Mais-/Weizenkörner geben — die Verdauung wärmt den Körper über Nacht!',
