          'Was im Garten für Hühner echte Superfoods sind — und was niemals in den Auslauf gehört:\n• HÜHNER-SUPERFOODS AUS DEM GARTEN:\n  – Oregano & Thymian (frisch, getrocknet oder als abgekühlter starker Tee ins Trinkwasser): Enthält natürliche ätherische Öle (Carvacrol/Thymol), die Darmflora und Immunabwehr gegen Kokzidien stärken!\n  – Vogelmiere, Löwenzahn, Giersch, junge Brennnesseln (leicht angewelkt oder getrocknet im Winter aufgehängt): Vitaminbomben für tiefdunkle, dottergelbe Eier!\n  – Kürbis (halbiert im Herbst als Beschäftigungs-Pickspaß!) inkl. Kürbiskernen (leicht darmpflegend).\n  – Knoblauch (1–2 zerdrückte Zehen pro 3–4 L Wasser alle 2 Wochen) & Apfelessig (1 EL naturtrüb auf 5 L Wasser in Plastiktränke — NICHT in verzinkten Metalltränken wegen Zinkreaktion!).\n• ABSOLUTE TABUS & GIFTIGES:\n  – Niemals Avocado (Persin ist für Vögel hochgiftig!), Schokolade, Koffein, rohe Bohnen, stark gesalzene/gewürzte Speisereste oder verschimmeltes Brot (Schimmelpilzgifte!) füttern.\n  – Grüne Kartoffelschalen, Kartoffelkeime und grüne Tomatenstrünke enthalten Solanin -> auf den geschlossenen Kompost statt in den Auslauf!\n  – Giftige Gartenpflanzen fern vom Gehege halten: Eibe (hochgiftig!), Fingerhut, Eisenhut, Maiglöckchen, Engelstrompete, Goldregen, Rhabarberblätter in großer Menge.',
