        content:
          'Eine Besonderheit der Kaninchen-Biologie sollte jeder Halter im Schlaf kennen:\n• DAS „STOPFMAGEN“-PRINZIP (Wichtigster Gesundheits-Fakt!):\n  – Kaninchen haben kaum eigene Darmmuskulatur! Der Nahrungsbrei wird nur dadurch weitergeschoben, dass oben regelmäßig neues faseriges Futter (Heu/Wiese) nachkommt („Stopfmagen“). Zudem können Kaninchen nicht erbrechen!\n  – ALARMZEICHEN: Frisst ein Kaninchen länger als 10–12 Stunden NICHTS, setzt keine Köttel mehr ab, hockt zusammengekauert mit aufgeblähtem Bauch oder knirscht laut mit den Zähnen -> AKUTER NOTFALL (Magenüberladung / Trommelsucht / Darmstillstand)! Nicht „bis morgen abwarten“, sondern am selben Tag zum heimtierkundigen Tierarzt!\n• VORBEUGUNG IM ALLTAG:\n  – IMMER Heu rund um die Uhr verfügbar (niemand darf ein Kaninchen vor einer OP oder aus sonstigem Grund nüchtern setzen!).\n  – Frisches Grün im Frühjahr (Löwenzahn, Klee, Kohl) stets über 1–2 Wochen langsam in kleinen Portionen einschleichen, damit sich die Darmbakterien anpassen können. Niemals warm gewordenes, gärendes Rasenmäher-Gras füttern (sofortige tödliche Aufgasung — Gras immer frisch mit der Sense/Sichel schneiden!).\n• SCHNUPFEN & WUNDE LÄUFE VERMEIDEN:\n  – Zugluft im Stall ist der Hauptauslöser für Kaninchenschnupfen (Pasteurellen) — Stall immer mindestens dreiseitig winddicht, aber ohne stickige Ammoniak-Luft!\n  – Harte Gitterböden sind tierschutzwidrig und verursachen schmerzhafte wunde Läufe (Pododermatitis); immer dickes weiches Stroh über saugfähiger Einstreu anbieten.\n• RHD / MYXOMATOSE: Jährliche Kombi-Impfung (z.B. Nobivac Myxo-RHD Plus) im Frühjahr schützt vor beiden verheerenden Seuchen (werden auch durch Stechmücken & frisches Wiesenfutter übertragen!).',
